        try teaqlNormalizeGraph()
        guard try teaqlValidateInputGraph() else { return entity }
        return try await context.executeGraphSave(comment: reason, rootEntityType: "OrderStatus", preparing: { context, session in
            try teaqlValidateLoadedIdentities()
            try teaqlNormalizeGraph()
            _ = try teaqlValidateInputGraph()
            try teaqlPreflightGraph(context, session: session)
            // A later Fix can add an intent to an already visited owner.
            // Re-admit the entire graph before customer policy or provider I/O.
            try teaqlNormalizeGraph()
            _ = try teaqlValidateInputGraph()
        }) { context, session in
            _ = try await teaqlSavePreflighted(context, session: session,
                scope: session.scope(key: entity.teaqlEntityKey))
            return try entity.teaqlRebuildSavedGraph(session.readback())
        }
    }

    /// Executes a node whose complete aggregate graph was already preflighted
    /// by the public save entry point. Generated cascade code must use this
    /// path so policy review remains a strict preflight-then-mutate sequence.
    func teaqlSavePreflighted(_ context: UserContext, session: GraphMutationSession,
                            scope: TraceScopeToken) async throws -> OrderStatus {
        guard try session.visitEntity(entity, phase: .write) else {
            return try entity.teaqlRebuildSavedGraph(session.readback())
        }
        if try entity.teaqlIsCancelledNew() { return entity }
        let saved = try await AuditedEntity(entity: entity, reason: reason)
            .saveInGraph(context, session: session, scope: scope)
        let activeScope = try scope.assigning(entity.teaqlEntityKey,
            to: EntityKey(entity: "OrderStatus", id: .int(saved.id)))
        for (index, var child) in entity.customerOrderList.enumerated() {
            if try child.teaqlIsCancelledNew() { continue }
            try child.teaqlAttachRoot(entity.teaqlEntityRoot)
            // The runtime resolves declared temporary references in its private
            // outgoing mutation. Never change a reviewed caller ledger here.
            let localReason = child.teaqlEntityRoot.localAuditReason(child.teaqlEntityKey)
            let childScope = try session.scope(key: child.teaqlEntityKey,
                localReason: localReason, parent: activeScope)
            do {
                _ = try await CustomerOrderAudited(entity: child, reason: localReason ?? reason)
                    .teaqlSavePreflighted(context, session: session, scope: childScope)
            }
            catch let error as CheckException {
                let prefix = ObjectLocation.property("customer_order_list").index(index)
                throw CheckException(context.translateCheckResults(error.violations.map { violation in
                    violation.prefixed(by: prefix)
                }))
            }
        }
        return saved
    }

    /// Check all original identities without attaching ledgers or changing FKs.
    func teaqlValidateLoadedIdentities() throws {
        if try entity.teaqlIsCancelledNew() { return }
        try AuditedEntity(entity: entity, reason: reason).validateLoadedIdentity()
        for child in entity.customerOrderList {
            try CustomerOrderAudited(entity: child, reason: reason).teaqlValidateLoadedIdentities()
        }
    }

    func teaqlNormalizeGraph() throws {
        if try entity.teaqlIsCancelledNew() { return }
        LoadedScalarRestoration.discardRestoredFields(of: entity)
        for var child in entity.customerOrderList {
            if try child.teaqlIsCancelledNew() { continue }
            try child.teaqlAttachRoot(entity.teaqlEntityRoot)
            if child.status != entity.teaqlPreflightID {
                child.updateStatus(entity.teaqlPreflightID)
            }
            let childReason = child.teaqlEntityRoot.localAuditReason(child.teaqlEntityKey) ?? reason
            try CustomerOrderAudited(entity: child, reason: childReason).teaqlNormalizeGraph()
        }
    }

    func teaqlValidateInputGraph() throws -> Bool {
        if try entity.teaqlIsCancelledNew() { return false }
        var pending = try AuditedEntity(entity: entity, reason: reason).validateVersion()
        if pending && entity.version != 0 && !entity.teaqlEntityRoot.isNew(entity.teaqlEntityKey) {
            if !entity.isLoaded(OrderStatus.__TeaqlFields.ID_PROPERTY_member) {
                throw CheckException([CheckResult(ruleID: "invalid_type", location: .property(OrderStatus.__TeaqlFields.ID_PROPERTY_model), message: "Mutation requires a fully loaded entity", entityType: "OrderStatus")])
            }
            if !entity.isLoaded(OrderStatus.__TeaqlFields.NAME_PROPERTY_member) {
                throw CheckException([CheckResult(ruleID: "invalid_type", location: .property(OrderStatus.__TeaqlFields.NAME_PROPERTY_model), message: "Mutation requires a fully loaded entity", entityType: "OrderStatus")])
            }
            if !entity.isLoaded(OrderStatus.__TeaqlFields.CODE_PROPERTY_member) {
                throw CheckException([CheckResult(ruleID: "invalid_type", location: .property(OrderStatus.__TeaqlFields.CODE_PROPERTY_model), message: "Mutation requires a fully loaded entity", entityType: "OrderStatus")])
            }
            if !entity.isLoaded(OrderStatus.__TeaqlFields.COLOR_PROPERTY_member) {
                throw CheckException([CheckResult(ruleID: "invalid_type", location: .property(OrderStatus.__TeaqlFields.COLOR_PROPERTY_model), message: "Mutation requires a fully loaded entity", entityType: "OrderStatus")])
            }
            if !entity.isLoaded(OrderStatus.__TeaqlFields.DISPLAY_ORDER_PROPERTY_member) {
                throw CheckException([CheckResult(ruleID: "invalid_type", location: .property(OrderStatus.__TeaqlFields.DISPLAY_ORDER_PROPERTY_model), message: "Mutation requires a fully loaded entity", entityType: "OrderStatus")])
            }
            if !entity.isLoaded(OrderStatus.__TeaqlFields.COMMERCE_PLATFORM_PROPERTY_member) {
                throw CheckException([CheckResult(ruleID: "invalid_type", location: .property(OrderStatus.__TeaqlFields.COMMERCE_PLATFORM_PROPERTY_model), message: "Mutation requires a fully loaded entity", entityType: "OrderStatus")])
            }
            if !entity.isLoaded(OrderStatus.__TeaqlFields.VERSION_PROPERTY_member) {
                throw CheckException([CheckResult(ruleID: "invalid_type", location: .property(OrderStatus.__TeaqlFields.VERSION_PROPERTY_model), message: "Mutation requires a fully loaded entity", entityType: "OrderStatus")])
            }
        }
        for (index, var child) in entity.customerOrderList.enumerated() {
            if try child.teaqlIsCancelledNew() { continue }
            try child.teaqlAttachRoot(entity.teaqlEntityRoot)
            if child.status != entity.teaqlPreflightID {
                child.updateStatus(entity.teaqlPreflightID)
            }
            let childReason = child.teaqlEntityRoot.localAuditReason(child.teaqlEntityKey) ?? reason
            do {
                // Evaluate every child, even when the owner already has work.
                let childPending = try CustomerOrderAudited(entity: child, reason: childReason).teaqlValidateInputGraph()
                if childPending { pending = true }
            } catch let error as CheckException {
                let prefix = ObjectLocation.property("customer_order_list").index(index)
                throw CheckException(error.violations.map { violation in
                    violation.prefixed(by: prefix)
                })
            }
        }
        return pending
    }

    func teaqlPreflightGraph(_ context: UserContext, session: GraphMutationSession) throws {
        guard try session.visitEntity(entity, phase: .preflight) else { return }
        if try entity.teaqlIsCancelledNew() { return }
        if entity.version != 0 && !entity.teaqlEntityRoot.isNew(entity.teaqlEntityKey)
            && entity.teaqlEntityRoot.hasPending(entity.teaqlEntityKey) {
            if !entity.isLoaded(OrderStatus.__TeaqlFields.ID_PROPERTY_member) {
                throw CheckException([CheckResult(ruleID: "invalid_type", location: .property(OrderStatus.__TeaqlFields.ID_PROPERTY_model), message: "Mutation requires a fully loaded entity", entityType: "OrderStatus")])
            }
            if !entity.isLoaded(OrderStatus.__TeaqlFields.NAME_PROPERTY_member) {
                throw CheckException([CheckResult(ruleID: "invalid_type", location: .property(OrderStatus.__TeaqlFields.NAME_PROPERTY_model), message: "Mutation requires a fully loaded entity", entityType: "OrderStatus")])
            }
            if !entity.isLoaded(OrderStatus.__TeaqlFields.CODE_PROPERTY_member) {
                throw CheckException([CheckResult(ruleID: "invalid_type", location: .property(OrderStatus.__TeaqlFields.CODE_PROPERTY_model), message: "Mutation requires a fully loaded entity", entityType: "OrderStatus")])
            }
            if !entity.isLoaded(OrderStatus.__TeaqlFields.COLOR_PROPERTY_member) {
                throw CheckException([CheckResult(ruleID: "invalid_type", location: .property(OrderStatus.__TeaqlFields.COLOR_PROPERTY_model), message: "Mutation requires a fully loaded entity", entityType: "OrderStatus")])
            }
            if !entity.isLoaded(OrderStatus.__TeaqlFields.DISPLAY_ORDER_PROPERTY_member) {
                throw CheckException([CheckResult(ruleID: "invalid_type", location: .property(OrderStatus.__TeaqlFields.DISPLAY_ORDER_PROPERTY_model), message: "Mutation requires a fully loaded entity", entityType: "OrderStatus")])
            }
            if !entity.isLoaded(OrderStatus.__TeaqlFields.COMMERCE_PLATFORM_PROPERTY_member) {
                throw CheckException([CheckResult(ruleID: "invalid_type", location: .property(OrderStatus.__TeaqlFields.COMMERCE_PLATFORM_PROPERTY_model), message: "Mutation requires a fully loaded entity", entityType: "OrderStatus")])
            }
            if !entity.isLoaded(OrderStatus.__TeaqlFields.VERSION_PROPERTY_member) {
                throw CheckException([CheckResult(ruleID: "invalid_type", location: .property(OrderStatus.__TeaqlFields.VERSION_PROPERTY_model), message: "Mutation requires a fully loaded entity", entityType: "OrderStatus")])
            }
        }
        try AuditedEntity(entity: entity, reason: reason).preflight(context)
        for (index, var child) in entity.customerOrderList.enumerated() {
            if try child.teaqlIsCancelledNew() {
                try CustomerOrderAudited(entity: child, reason: reason).teaqlPreflightGraph(context, session: session)
                continue
            }
            try child.teaqlAttachRoot(entity.teaqlEntityRoot)
            if child.status != entity.teaqlPreflightID {
                child.updateStatus(entity.teaqlPreflightID)
            }
            let childReason = child.teaqlEntityRoot.localAuditReason(child.teaqlEntityKey) ?? reason
            if entity.id == 0 {
                try context.bindGraphReference(child, field: "status", to: entity)
            }
            do { try CustomerOrderAudited(entity: child, reason: childReason).teaqlPreflightGraph(context, session: session) }
            catch let error as CheckException {
                let prefix = ObjectLocation.property("customer_order_list").index(index)
                throw CheckException(context.translateCheckResults(error.violations.map { violation in
                    violation.prefixed(by: prefix)
                }))
            }
        }
    }
